INSERT INTO `php_topics_detail_copy` (`id`, `id_topics`, `title`, `description`, `folder_path`, `picturePath`, `controller`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 7, 'Persyaratan', '<h3>Persyaratan Minimum</h3>\n<ul>\n  <li>Prosesor: Intel Core 2 duo atau Setara</li>\n  <li>Memori: 4 GB</li>\n  <li>Hardisk: 120 GB HDD dengan penyimpanan tersedia minimal 20 GB</li>\n  <li>Koneksi: Ethernet and Wi-Fi capabilities</li>\n</ul>\n<h3>Persyaratan Rekomendasi</h3>\n<ul>\n  <li>Prosesor: Intel Core i3 atau Setara</li>\n  <li>Memori: 4 GB</li>\n  <li>Hardisk: 120 GB SSD dengan penyimpanan tersedia minimal 20 GB</li>\n  <li>Koneksi: Ethernet and Wi-Fi capabilities</li>\n</ul>\n<h2>Perangkat Lunak yang Dibutuhkan</h2>\n<ul>\n  <li>Sistem Operasi: Windows 8.1 atau terbaru</li>\n  <li>Editor Teks: Visual Studio Code : Versi Stabil Terbaru Diinstal</li>\n  <li>Browser: Chrome, Firefox, Safari, Edge</li>\n  <li>Server: Xampp</li>\n  <li>Koneksi: Ethernet and Wi-Fi capabilities</li>\n</ul>\n', NULL, NULL, 'persyaratan', 'draft', NULL, NULL, NULL),
(2, 7, 'Installasi Xampp', '<p> Visual Studio Code (VSCode) adalah kode editor open source dan gratis yang dibuat oleh Microsoft. Untuk dokumen panduan ini akan menggunakan VSCode untuk membuat dan mengedit proyek website. </p>\r\n<p> Untuk menjalankan VSCode, selesaikan proses instalasi menggunakan langkah – langkah berikut : </p>\r\n<p> 1. Silahkan unduh VSCode dari website resminya, <a href=\'https://code.visualstudio.com/\'> link. </a>\r\n</p>\r\n<p> 2. </p>\r\n<table cellpadding=\'0\' cellspacing=\'0\'>\r\n <tbody>\r\n  <tr>\r\n   <td width=\'108\' height=\'0\'></td>\r\n  </tr>\r\n  <tr>\r\n   <td></td>\r\n   <td>\r\n\r\n   </td>\r\n  </tr>\r\n </tbody>\r\n</table>\r\n<br clear=\'ALL\' />\r\n<p> Unduh file yang sesuai dengan sistem operasi Anda. Klik pada tombol unduh dan pilih folder untuk menyimpan file VSCode kemudian memulai proses unduh </p>\r\n<p> Gambar 1 Visual Studio Code Halaman Resmi </p>\r\n<br clear=\'all\' />\r\n<p> 3. </p>\r\n<table cellpadding=\'0\' cellspacing=\'0\'>\r\n <tbody>\r\n  <tr>\r\n   <td width=\'111\' height=\'0\'></td>\r\n  </tr>\r\n  <tr>\r\n   <td></td>\r\n   <td>\r\n       </td>\r\n  </tr>\r\n </tbody>\r\n</table>\r\n<br clear=\'ALL\' />\r\n<p> Setelah proses unduh selesai silahkan jalankan file visual studio code yang telah ter-unduh pada komputer / laptop Anda. </p>\r\n<p> Gambar 2 VSCode Lisensi Persetujuan </p>\r\n<p> 4. </p>\r\n<table cellpadding=\'0\' cellspacing=\'0\'>\r\n <tbody>\r\n  <tr>\r\n   <td width=\'108\' height=\'0\'></td>\r\n  </tr>\r\n  <tr>\r\n   <td></td>\r\n   <td>\r\n    </td>\r\n  </tr>\r\n </tbody>\r\n</table>\r\n<br clear=\'ALL\' />\r\n<p> Ikuti petujuntuk yang diberikan oleh file installer untuk menyelesaikan proses instalasi. pilih pada bagian “Add To PATH” untuk menginjinkan membuka VSCode melalui </p>\r\n<em>command line</em>\r\n<p> atau terminal dengan perintah sederhana “code .” </p>\r\n<p> Gambar 3 Tugas Tambahan Instalasi </p>\r\n<p> 5. Pengaturan terakhir untuk melakukan instalasi VSCode dengan klik pada “Install” \r\n</p>\r\n<p> Gambar 4 Ringkasan Instalasi VSCode. </p>\r\n<table cellpadding=\'0\' cellspacing=\'0\' align=\'left\'>\r\n <tbody>\r\n  <tr>\r\n   <td width=\'254\' height=\'0\'></td>\r\n  </tr>\r\n  <tr>\r\n   <td></td>\r\n   <td>\r\n       </td>\r\n  </tr>\r\n </tbody>\r\n</table>\r\n<br clear=\'ALL\' />\r\n<p> Gambar 5 Proses Instalasi VSCode </p>\r\n<br clear=\'all\' />\r\n<p> 6. </p>\r\n<table cellpadding=\'0\' cellspacing=\'0\'>\r\n <tbody>\r\n  <tr>\r\n   <td width=\'108\' height=\'0\'></td>\r\n  </tr>\r\n  <tr>\r\n   <td></td>\r\n   <td></td>\r\n  </tr>\r\n </tbody>\r\n</table>\r\n<br clear=\'ALL\' />\r\n<p> Setelah instalasi selesai, untuk membuka VSCode cukup temukan aplikasi dengan menekan pada logo Windows di keyboard atau taskbar. VSCode juga dapat dibuka melalui', NULL, NULL, 'installasi_xampp', 'draft', NULL, NULL, NULL),
(3, 7, 'Installasi Visual Studio Code', '', NULL, NULL, 'installasi_visual_studio_code', 'draft', NULL, NULL, NULL);
