INSERT INTO `ui_topics` (`id`, `level`, `name`, `note`, `projectname`, `projectpath`, `packname`, `description`, `guidepath`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 'Linear Layout - Hello World', 'Linear Layout is a view group that aligns all children in a single direction, vertically or horizontally. You can specify the layout direction with the \"android:orientation\" attribute.\r\n*Info: you can reload your previous work, by pressing \'Load Source Code\' in the Results section (below)', 'HelloWorld', 'UI01\\HelloWorld', 'org.aplas.helloworld', 'This topic contains lesson materials and assignments on how to create hello world text using Textview on a vertical linear layout', 'uilearningfile/y8wgPLoAUZpUhFRJLRYDcFvwLT1dqUuutqo1xxNP.pdf', 1, '2021-05-30 10:17:07', '2021-05-30 04:17:07'),
(2, 1, 'Linear Layout - Email & Password', 'Linear Layout is a view group that aligns all children in a single direction, vertically or horizontally. You can specify the layout direction with the \"android:orientation\" attribute.\r\n*Info: you can reload your previous work, by pressing \'Load Source Code\' in the Results section (below)', 'EmailPassword', 'UI02\\EmailPassword', 'org.aplas.emailpassword', 'This topic contains lesson materials and assignments on how to create email and password input using EditText on a linear layout vertically', 'uilearningfile/A26pg3yhqauA8S2TytFURtEqjbfQf9v4nqhP3C3n.pdf', 1, '2021-05-30 10:17:18', '2021-05-30 04:17:18'),
(3, 1, 'Linear Layout - Exit & Login Button', '*Info: you can reload your previous work, by pressing \'Load Source Code\' in the Results section (below)', 'ExitLogin', 'UI03\\ExitLogin', 'org.aplas.exitlogin', 'This topic contains lesson materials and assignments on how to create and position the Exit & Login buttons using the Button on a linear layout horizontally', 'uilearningfile/czHRIvDGzOdJj5kALtSPB1yuGF936ljKTF47k8oV.pdf', 1, '2021-05-30 10:17:23', '2021-05-30 04:17:23'),
(4, 1, 'Linear Layout - Nested View', '*Info: you can reload your previous work, by pressing \'Load Source Code\' in the Results section (below)', 'NestedView', 'UI04\\NestedView', 'org.aplas.nestedview', 'This topic contains lesson material and assignments on how to create and position components horizontally in a vertical linear layout with a nested view', 'uilearningfile/sE4KgtbBoAM8678dft3mP3dDwGvEKf9i9svHNjZi.pdf', 1, '2021-05-30 10:17:30', '2021-05-30 04:17:30'),
(5, 1, 'Linear Layout - Simple Login Page', '*Info: you can reload your previous work, by pressing \'Load Source Code\' in the Results section (below)', 'LinearLogin', 'UI05\\LinearLogin', 'org.aplas.linearlogin', 'this is the last topic for linear layout. contains lesson material and assignments on how to create a simple login page using a vertical linear layout and nested views.', 'uilearningfile/h2jWY0TELydGow8JZyGtzI5Hk8Tu6nDrxhEVuUK1.pdf', 1, '2021-05-30 10:17:41', '2021-05-30 04:17:41'),
